import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import '../../../../core/database/app_database.dart';import '../../../../core/database/tables.dart';
class SplashPage extends StatefulWidget{const SplashPage({super.key});@override State<SplashPage> createState()=>_SplashState();}class _SplashState extends State<SplashPage>{@override void initState(){super.initState();Future.delayed(const Duration(milliseconds:700),()async{final d=await AppDatabase.instance.database;final p=await d.query(Tables.profile,limit:1);if(mounted)context.go(p.isEmpty?'/onboarding':'/path');});}@override Widget build(BuildContext c)=>const Scaffold(body:Center(child:CircularProgressIndicator()));}
